  height: 100%;
  margin: 0;
  padding: 0;
}

#app {
  height: 100%;
}

#app-root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.app-content {
  flex: 1;
}

.draggable {
  touch-action: none;
}
.front {
  z-index: 9999
}
.back {
  z-index: 0
}

/* Windows 98 Style Scrollbars */
::-webkit-scrollbar {
  width: 16px;
  height: 16px;
}

::-webkit-scrollbar-track {
  background: #c0c0c0;
  border: 1px solid #808080;
}

::-webkit-scrollbar-thumb {
  background: #c0c0c0;
  border: 1px solid #808080;
  border-top: 1px solid #ffffff;
  border-left: 1px solid #ffffff;
}

::-webkit-scrollbar-thumb:hover {
  background: #a0a0a0;
}

::-webkit-scrollbar-corner {
  background: #c0c0c0;
  border: 1px solid #808080;
  border-top: 1px solid #ffffff;
  border-left: 1px solid #ffffff;
}

/* Firefox scrollbar styling */
* {
  scrollbar-width: auto;
  scrollbar-color: #c0c0c0 #808080;
}

/* Resize functionality */
.resizable {
  /* position: relative; */
}

/* Show resize cursor on edges */
.resizable {
  cursor: default;
}

.resizable:hover {
  cursor: se-resize;
}

/* Make content responsive to container size */
.resizable .win-card {
  overflow: hidden;
}

.resizable .win-container,
.resizable .contact-content {
  width: 100% !important;
  height: 100% !important;
  box-sizing: border-box;
  overflow: hidden;
}

.resizable .win-card > img {
  width: 100%;
  height: auto;
  max-height: 100%;
}

/* Make buttons and content responsive */
.resizable .win-btn,
.resizable button {
  max-width: 100%;
  word-wrap: break-word;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.resizable .win-row {
  width: 100%;
  margin: 0;
}

.resizable .win-col {
  padding: 8px;
  min-width: 0;
}

/* Hide content when window is too small */
.resizable .win-container {
  min-height: 0;
}

/* Window shadows and 3D effects */
.window {
  box-shadow: 
    2px 2px 0px rgba(0,0,0,0.3),
    inset 1px 1px 0px rgba(255,255,255,0.8),
    inset -1px -1px 0px rgba(0,0,0,0.2);
  border: 1px solid #808080;
}

/* Enhanced window styling */
.win-card.window {
  border: 2px solid;
  border-color: #ffffff #808080 #808080 #ffffff;
  box-shadow:
    2px 2px 0px rgba(0,0,0,0.3),
    inset 1px 1px 0px rgba(255,255,255,0.8),
    inset -1px -1px 0px rgba(0,0,0,0.2);
}

/* Window animations */
.window-enter-active, .window-leave-active {
  transition: all 0.3s ease;
}

.window-enter-from {
  opacity: 0;
  transform: scale(0.8) translateY(-20px);
}

.window-leave-to {
  opacity: 0;
  transform: scale(0.8) translateY(20px);
}

/* Minimize/maximize animations */
.window-content-enter-active, .window-content-leave-active {
  transition: all 0.2s ease;
}

.window-content-enter-from, .window-content-leave-to {
  opacity: 0;
  transform: translateY(-10px);
}

/* ── Mobile layout ────────────────────────────────────────────── */
@media (max-width: 767px) {
  /* Shrink the decorative header */
  .header-bar {
    height: 150px !important;
    overflow: hidden;
  }

  /* Stack windows vertically in normal flow */
  .app-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    padding: 8px !important;
  }

  /* Reset absolute/fixed positioning so windows flow naturally */
  .draggable {
    position: static !important;
    transform: none !important;
    touch-action: auto !important;
    width: 100%;
  }

  /* Full-width windows */
  .draggable > .win-card,
  .win-card.draggable {
    width: 100% !important;
    position: static !important;
    left: auto !important;
    top: auto !important;
    box-sizing: border-box;
  }

  /* Thinner scrollbars on mobile */
  ::-webkit-scrollbar {
    width: 4px;
    height: 4px;
  }
}
</style>
